<script setup lang="ts">
definePageMeta({layout:'consumer'})
interface Series {parameterName:string;testId:string;unit?:string;observations:{reportId:string;originalValue:string;originalUnit?:string;date:string|null;referenceRange:string|null;notPlottedReason:string|null}[];dataPoints:{date:string;value:number}[];unplottedCount:number}
const {profileId,request,requireSession}=useConsumer();const series=ref<Series[]>([]),query=ref(''),loading=ref(true),error=ref('')
useHead({title:'Trends | Doclyzer'})
async function load(){const id=profileId.value;series.value=[];loading.value=true;error.value='';if(!id){loading.value=false;return}try{const data=await request<{parameters:Series[]}>(`/reports/lab-trends?profileId=${encodeURIComponent(id)}`);if(id===profileId.value)series.value=data.parameters}catch(cause){error.value=(cause as Error).message}finally{loading.value=false}}
onMounted(async()=>{try{if(await requireSession())await load()}catch(cause){error.value=(cause as Error).message;loading.value=false}});watch(profileId,()=>void load())
const filtered=computed(()=>series.value.filter(s=>s.parameterName.toLowerCase().includes(query.value.toLowerCase())))
</script>
<template><div><header class="page-heading"><div><p class="eyebrow">Over time</p><h1>Trends</h1><p class="muted">Only compatible measurements share a chart. Unknown dates and values stay visible in the detail list.</p></div></header><label class="field">Find a test<input v-model="query" type="search" placeholder="Search test names" /></label><p v-if="error" class="alert error" role="alert">{{ error }} <button class="secondary" @click="load">Retry</button></p><p v-if="loading" role="status">Loading trends…</p><div v-else-if="!filtered.length" class="empty"><h2>{{ query ? 'No matching tests' : 'No trends yet' }}</h2><p v-if="!query">Results will appear after a report has been processed.</p><NuxtLink v-if="!query" class="button" to="/reports/upload">Add report</NuxtLink></div><div v-else class="grid"><NuxtLink v-for="s in filtered" :key="`${s.testId}:${s.unit}`" class="card trend" :to="`/trends/${encodeURIComponent(s.parameterName)}?unit=${encodeURIComponent(s.unit??'')}`"><p class="eyebrow">{{ s.observations.length }} observation{{ s.observations.length===1?'':'s' }}</p><h2>{{ s.parameterName }}</h2><p>{{ s.unit ?? 'Unit not recorded' }}</p><p class="muted">{{ s.dataPoints.length }} chartable · {{ s.unplottedCount }} need review</p></NuxtLink></div></div></template>
<style scoped>.trend{text-decoration:none;color:inherit}.trend:hover{border-color:#75a47c}.trend h2{overflow-wrap:anywhere}</style>
